effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec2 c = uv * 2.0 - 1.0;
  float r2 = dot(c, c);
  vec2 w = c * (1.0 + curvature * r2 * mixAmt);
  uv = w * 0.5 + 0.5;
  vec4 src = texture2DCv(inputImg.texture, clamp(uv, 0.0, 1.0));
  float a = max(src.a, 1e-4);
  vec3 col = src.rgb / a;
  float mask = 1.0 - mask * (0.5 + 0.5 * sin(uv.x * acScreenSize.x * 2.1));
  float scan = 1.0 - scan * (0.5 + 0.5 * sin(uv.y * acScreenSize.y * 1.5));
  float vig = 1.0 - edge * smoothstep(0.4, 1.4, r2);
  col *= mix(1.0, mask * scan * vig, mixAmt);
  gl_FragColor = vec4(col * src.a, src.a);
}
